def metric(z,y):
    top=z.max(1);loss=top+np.log(np.exp(z-top[:,None]).sum(1))-z[np.arange(y.size),y];return np.array([np.count_nonzero(z.argmax(1)==y)/y.size,loss.mean()])
def main():
    p=json.loads((OUT/'protocol.json').read_text());prep=guard(p);parent_closed();s=json.loads((OUT/'statistics.json').read_text());m=json.loads((OUT/'manifest.json').read_text());raw=np.load(OUT/'statistical_arrays.npz');parent=np.load(PARENT/'statistical_arrays.npz');assert s['producer_manifest_sha256']==sha(OUT/'manifest.json') and s['count_audit_sha256']==sha(OUT/'evidence_audit.json') and s['parent_statistics_sha256']==sha(PARENT/'statistics.json') and s['parent_statistical_arrays_sha256']==sha(PARENT/'statistical_arrays.npz');assert s['control_logits_sha256']==sha(OUT/'control_logits.npz') and s['statistical_arrays_sha256']==sha(OUT/'statistical_arrays.npz');d=np.load(prep['data_path']);x=d['test_inputs'].astype(float).reshape(1250,8,64);labels=d['test_labels'];values=np.empty((3,5,10,2));rows={r['name']:r for r in s['rows']}
    for r in m['rows']:
        assert sha(r['path'])==r['sha256'];v=metric(np.load(r['path'])['logits'],labels);bi=p['samples'].index(r['T']);values[bi,r['model'],r['seed']]=v;np.testing.assert_allclose(v,[rows[r['name']]['accuracy'],rows[r['name']]['mean_CE']],rtol=2e-12,atol=2e-13)
    np.testing.assert_allclose(values,raw['values'],rtol=2e-12,atol=2e-13);names=['ACT8_FP32_weights','ACT8_INT2_weights','ACT8_INT4_weights','ACT8_INT8_weights','ACT8_programmed_weight_mean'];cm=np.empty((5,5,2));saved=np.load(OUT/'control_logits.npz');cr={(r['condition'],r['model']):r for r in s['controls']}
    for mi,item in enumerate(prep['models']):
        model=np.load(item['controls_path'])
        for ci,name in enumerate(names):
            h=x.copy()
            for layer in [0,1]:
                w=model[f'weight_{layer}'].astype(float)
                if ci==4:
                    f=model[f'weight_field_{layer}'].astype(float);w=np.exp(-np.logaddexp(0,-2*f));np.testing.assert_allclose(w,1/(1+np.exp(-2*f)),rtol=1e-14,atol=1e-16)
                elif ci:levels=2**[2,4,8][ci-1]-1;w=np.round(w*levels)/levels
                low=float(model['input_lower'] if layer==0 else model['hidden_lower']);span=float(model['input_span'] if layer==0 else model['hidden_span']);code=np.round(np.minimum(1,np.maximum(0,(h-low)/span))*255).astype(np.uint8);y=low*w.sum(0)+(span/255)*np.matmul(code.astype(float),w)+model[f'bias_{layer}'];h=np.maximum(y,0) if layer==0 else y
            z=saved[f'control{ci}_model{mi}'];np.testing.assert_allclose(h.reshape(10000,10),z,rtol=2e-12,atol=2e-11);np.testing.assert_array_equal(h.reshape(10000,10).argmax(1),z.argmax(1));v=metric(z,labels);cm[ci,mi]=v;np.testing.assert_allclose(v,[cr[name,mi]['accuracy'],cr[name,mi]['mean_CE']],rtol=2e-12,atol=2e-13)
    np.testing.assert_allclose(cm,raw['control_metrics'],rtol=2e-12,atol=2e-13)
    for ci,name in enumerate(names):np.testing.assert_allclose(cm[ci].mean(0),s['control_summary'][name],rtol=2e-12,atol=2e-13)
    for summary in s['summaries']:
        bi=p['samples'].index(summary['T']);np.testing.assert_allclose(values[bi].mean((0,1)),summary['mean'],rtol=2e-12,atol=2e-13);np.testing.assert_allclose(values[bi].mean(1),summary['model_means'],rtol=2e-12,atol=2e-13);assert summary['hidden_clipped_coordinates']==sum(r['hidden_clipped_coordinates'] for r in m['rows'] if r['T']==summary['T'])
    bm,bs=parent['bootstrap_models'],parent['bootstrap_seeds']
    for c in s['contrasts']:
        bi=c['budget_index'];name=c['contrast'];ref=parent['values'][0,bi] if name=='integer8_minus_R1' else parent['values'][1,bi] if name=='integer8_minus_R3_equal_updates' else parent['baseline_metrics'][0,:,None,:];delta=values[bi]-ref;dist=sum(delta[bm[:,i,None],bs[:,i,:]].sum(1) for i in range(5))/50;np.testing.assert_allclose(dist,raw[f'{name}_budget{bi}'],rtol=2e-10,atol=2e-12);np.testing.assert_allclose(delta.mean((0,1)),c['difference'],rtol=2e-10,atol=2e-12);np.testing.assert_allclose(np.quantile(dist,[.025,.975],axis=0).T,c['descriptive_95_interval'],rtol=2e-10,atol=2e-12)
